-- 20261012180000_modernize_email_templates.sql
-- Modernisation intégrale des modèles de courriels transactionnels :
-- Rendu sobre, moderne, raffiné et statutaire (Fintech UMOA).

insert into public.notification_templates (slug, language, subject, body_html, variables)
values
  -- 1. KYC Validé
  ('kyc_completed', 'fr', 'Votre dossier KYC a été approuvé',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Identité validée</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Votre dossier KYC a été approuvé</h1><p style="margin: 0 0 16px; font-size: 15px; line-height: 1.6; color: #334155;">Bonjour <strong>{{client_firstname}}</strong>,</p><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Nous vous informons que vos pièces d''identité ont été vérifiées et validées avec succès par notre équipe de conformité.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 18px 20px; margin-bottom: 24px;"><p style="margin: 0 0 8px; font-size: 13px; font-weight: 600; color: #0f172a;">Votre compte bénéficie désormais de tous les privilèges :</p><ul style="margin: 0; padding-left: 18px; font-size: 14px; line-height: 1.6; color: #475569;"><li>Plafonds de transaction entièrement débloqués</li><li>Accès complet aux demandes de crédit</li><li>Opérations de dépôt et retrait Mobile Money activées</li></ul></div><div style="text-align: center; margin: 28px 0 12px;"><a href="https://azari-microfinance.site/client/dashboard" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Accéder à mon espace client</a></div>',
   '["client_firstname"]'),

  ('kyc_completed', 'en', 'Your KYC file has been approved',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Identity Approved</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Your KYC file has been approved</h1><p style="margin: 0 0 16px; font-size: 15px; line-height: 1.6; color: #334155;">Hello <strong>{{client_firstname}}</strong>,</p><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">We are pleased to inform you that your identity documents have been verified and approved by our compliance team.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 18px 20px; margin-bottom: 24px;"><p style="margin: 0 0 8px; font-size: 13px; font-weight: 600; color: #0f172a;">Your account is now fully verified:</p><ul style="margin: 0; padding-left: 18px; font-size: 14px; line-height: 1.6; color: #475569;"><li>Transaction limits expanded</li><li>Full access to loan applications</li><li>Direct deposits and mobile money withdrawals unlocked</li></ul></div><div style="text-align: center; margin: 28px 0 12px;"><a href="https://azari-microfinance.site/client/dashboard" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Access my account</a></div>',
   '["client_firstname"]'),

  -- 2. KYC Rejeté
  ('kyc_rejected', 'fr', 'Votre dossier KYC nécessite une mise à jour',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #fef2f2; color: #b91c1c; border: 1px solid #fecaca;">Action requise</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Mise à jour de vos justificatifs requise</h1><p style="margin: 0 0 16px; font-size: 15px; line-height: 1.6; color: #334155;">Bonjour <strong>{{client_firstname}}</strong>,</p><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Après vérification par notre service conformité, une ou plusieurs pièces justificatives n''ont pas pu être validées (image floue, document expiré ou cadrage incomplet).</p><div style="background-color: #fffbeb; border: 1px solid #fde68a; border-radius: 10px; padding: 18px 20px; margin-bottom: 24px;"><p style="margin: 0 0 6px; font-size: 13px; font-weight: 600; color: #92400e;">Comment régulariser votre dossier ?</p><p style="margin: 0; font-size: 14px; line-height: 1.6; color: #78350f;">Connectez-vous à votre espace personnel pour consulter les remarques précises et téléverser une photo nette et lisible de votre pièce d''identité.</p></div><div style="text-align: center; margin: 28px 0 12px;"><a href="https://azari-microfinance.site/client/kyc" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Mettre à jour mes pièces</a></div>',
   '["client_firstname"]'),

  ('kyc_rejected', 'en', 'Your KYC file needs attention',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #fef2f2; color: #b91c1c; border: 1px solid #fecaca;">Action Required</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Document update required</h1><p style="margin: 0 0 16px; font-size: 15px; line-height: 1.6; color: #334155;">Hello <strong>{{client_firstname}}</strong>,</p><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Our compliance department was unable to approve your submitted documents (unclear image, expired document, or missing page).</p><div style="background-color: #fffbeb; border: 1px solid #fde68a; border-radius: 10px; padding: 18px 20px; margin-bottom: 24px;"><p style="margin: 0 0 6px; font-size: 13px; font-weight: 600; color: #92400e;">Next steps:</p><p style="margin: 0; font-size: 14px; line-height: 1.6; color: #78350f;">Please sign in to your dashboard to view the specific notes and upload a clear, legible copy of your document.</p></div><div style="text-align: center; margin: 28px 0 12px;"><a href="https://azari-microfinance.site/client/kyc" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Update documents</a></div>',
   '["client_firstname"]'),

  -- 3. Dépôt Confirmé
  ('deposit_confirmed', 'fr', 'Confirmation de votre dépôt',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Dépôt confirmé</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Votre compte a été crédité</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Nous vous confirmons le bon traitement et la validation définitive de votre opération de dépôt.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 4px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b;">Montant crédité</p><p style="margin: 0; font-size: 28px; font-weight: 800; color: #077bad; letter-spacing: -0.02em;">{{amount}} FCFA</p></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">Ces fonds sont d''ores et déjà disponibles sur votre solde pour vos opérations courantes ou la constitution de garantie de prêt.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/wallet" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Consulter mon portefeuille</a></div>',
   '["amount"]'),

  ('deposit_confirmed', 'en', 'Deposit confirmed',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Deposit Confirmed</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Your wallet has been credited</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">We confirm the successful execution and credit of your deposit order.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 4px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b;">Credited amount</p><p style="margin: 0; font-size: 28px; font-weight: 800; color: #077bad; letter-spacing: -0.02em;">{{amount}} FCFA</p></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">The funds are instantly available on your balance for standard operations or mandatory loan savings.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/wallet" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">View wallet</a></div>',
   '["amount"]'),

  -- 4. Dépôt Rejeté
  ('deposit_rejected', 'fr', 'Information sur votre tentative de dépôt',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #fef2f2; color: #b91c1c; border: 1px solid #fecaca;">Dépôt non validé</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Votre demande de dépôt n''a pas abouti</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Votre tentative de dépôt n''a pas pu être finalisée par l''opérateur de paiement.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 18px 20px; margin-bottom: 24px;"><p style="margin: 0 0 8px; font-size: 13px; font-weight: 600; color: #0f172a;">Causes usuelles :</p><ul style="margin: 0; padding-left: 18px; font-size: 14px; line-height: 1.6; color: #475569;"><li>Solde Mobile Money insuffisant lors de la confirmation</li><li>Dépassement du délai de validation sur votre téléphone</li><li>Annulation manuelle de la transaction</li></ul></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">Aucun débit n''a été effectué. Vous pouvez réitérer l''opération en toute sécurité à tout moment.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/wallet" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Retourner au portefeuille</a></div>',
   '[]'),

  ('deposit_rejected', 'en', 'Deposit rejected',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #fef2f2; color: #b91c1c; border: 1px solid #fecaca;">Deposit Failed</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Your deposit could not be completed</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Your recent deposit attempt was declined by the payment provider.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 18px 20px; margin-bottom: 24px;"><p style="margin: 0 0 8px; font-size: 13px; font-weight: 600; color: #0f172a;">Common reasons:</p><ul style="margin: 0; padding-left: 18px; font-size: 14px; line-height: 1.6; color: #475569;"><li>Insufficient funds on your Mobile Money account</li><li>Approval timeout on your device</li><li>Cancelled prompt on client phone</li></ul></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">No funds were charged. You may initiate a new deposit at any time.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/wallet" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Return to wallet</a></div>',
   '[]'),

  -- 5. Retrait Exécuté
  ('withdrawal_completed', 'fr', 'Confirmation de votre retrait',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Retrait effectué</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Votre retrait a été traité avec succès</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Votre ordre de retrait de fonds a été validé et envoyé vers votre destination de paiement.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 4px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b;">Montant transféré</p><p style="margin: 0; font-size: 28px; font-weight: 800; color: #0f172a; letter-spacing: -0.02em;">{{amount}} FCFA</p></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">Le crédit sur votre compte externe ou portefeuille Mobile Money intervient en quelques minutes à 24 heures ouvrées selon l''opérateur.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/wallet" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Consulter mon portefeuille</a></div>',
   '["amount"]'),

  ('withdrawal_completed', 'en', 'Withdrawal completed',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Withdrawal Completed</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Your withdrawal has been processed</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Your withdrawal request has been validated and dispatched to your recipient account.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 4px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b;">Transferred amount</p><p style="margin: 0; font-size: 28px; font-weight: 800; color: #0f172a; letter-spacing: -0.02em;">{{amount}} FCFA</p></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">Depending on the destination method, funds reflect instantly to within 24 business hours.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/wallet" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">View wallet history</a></div>',
   '["amount"]'),

  -- 6. Retrait Rejeté
  ('withdrawal_rejected', 'fr', 'Information sur votre demande de retrait',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #fef2f2; color: #b91c1c; border: 1px solid #fecaca;">Demande non validée</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Votre demande de retrait n''a pas pu être exécutée</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Nous n''avons pas pu donner une suite favorable à votre ordre de retrait. Le montant réservé a été immédiatement recrédité sur votre solde disponible.</p><div style="background-color: #fffbeb; border: 1px solid #fde68a; border-radius: 10px; padding: 18px 20px; margin-bottom: 24px;"><p style="margin: 0 0 8px; font-size: 13px; font-weight: 600; color: #92400e;">Motifs fréquents :</p><ul style="margin: 0; padding-left: 18px; font-size: 14px; line-height: 1.6; color: #78350f;"><li>Garantie obligatoire de prêt en attente de constitution</li><li>Coordonnées bancaires ou numéro de mobile incorrects</li><li>Vérifications de sécurité de conformité requises</li></ul></div><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/wallet" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Consulter mon solde</a></div>',
   '[]'),

  ('withdrawal_rejected', 'en', 'Withdrawal rejected',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #fef2f2; color: #b91c1c; border: 1px solid #fecaca;">Withdrawal Declined</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Your withdrawal request was declined</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">We could not execute your withdrawal. Any reserved funds have been immediately released back to your available balance.</p><div style="background-color: #fffbeb; border: 1px solid #fde68a; border-radius: 10px; padding: 18px 20px; margin-bottom: 24px;"><p style="margin: 0 0 8px; font-size: 13px; font-weight: 600; color: #92400e;">Potential causes:</p><ul style="margin: 0; padding-left: 18px; font-size: 14px; line-height: 1.6; color: #78350f;"><li>Pending loan guarantee requirement</li><li>Invalid bank details or inactive mobile wallet</li><li>Compliance verification checks</li></ul></div><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/wallet" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Review wallet</a></div>',
   '[]'),

  -- 7. Prêt Accepté
  ('loan_requests_accepted', 'fr', 'Votre demande de prêt a été acceptée',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Financement accordé</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Excellente nouvelle : votre prêt est approuvé</h1><p style="margin: 0 0 16px; font-size: 15px; line-height: 1.6; color: #334155;">Votre dossier de microcrédit a été validé avec succès par notre comité d''attribution.</p><div style="background-color: #f0f9ff; border: 1px solid #bae6fd; border-radius: 10px; padding: 18px 20px; margin-bottom: 24px;"><p style="margin: 0 0 6px; font-size: 13px; font-weight: 600; color: #0369a1;">Prochaine étape obligatoire :</p><p style="margin: 0; font-size: 14px; line-height: 1.6; color: #0c4a6e;">Consultez et signez votre contrat de prêt depuis votre espace sécurisé pour valider les conditions et débloquer les fonds.</p></div><div style="text-align: center; margin: 28px 0 12px;"><a href="https://azari-microfinance.site/client/loans" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Consulter et signer mon contrat</a></div>',
   '[]'),

  ('loan_requests_accepted', 'en', 'Your loan has been accepted',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Loan Approved</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Great news: your loan application is approved</h1><p style="margin: 0 0 16px; font-size: 15px; line-height: 1.6; color: #334155;">Your financing request has been reviewed and approved by the credit committee.</p><div style="background-color: #f0f9ff; border: 1px solid #bae6fd; border-radius: 10px; padding: 18px 20px; margin-bottom: 24px;"><p style="margin: 0 0 6px; font-size: 13px; font-weight: 600; color: #0369a1;">Next step:</p><p style="margin: 0; font-size: 14px; line-height: 1.6; color: #0c4a6e;">Review and sign your loan contract from your secure client area to proceed with fund disbursement.</p></div><div style="text-align: center; margin: 28px 0 12px;"><a href="https://azari-microfinance.site/client/loans" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Sign my contract</a></div>',
   '[]'),

  -- 8. Prêt Décaissé
  ('loan_requests_disbursed', 'fr', 'Votre prêt a été décaissé',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Fonds versés</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Votre prêt est décaissé sur votre compte</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Nous vous confirmons le décaissement effectif de votre financement sur votre portefeuille Azari Microfinance.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 4px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b;">Montant décaissé</p><p style="margin: 0; font-size: 28px; font-weight: 800; color: #077bad; letter-spacing: -0.02em;">{{amount}} FCFA</p></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">Votre calendrier de remboursement ainsi que le tableau d''amortissement sont consultables à tout moment sur votre tableau de bord.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/loans" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Consulter mon prêt</a></div>',
   '["amount"]'),

  ('loan_requests_disbursed', 'en', 'Your loan has been disbursed',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Disbursement Complete</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Your loan funds are available</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">We confirm the official disbursement of your loan funds into your Azari Microfinance wallet.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 4px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b;">Disbursed amount</p><p style="margin: 0; font-size: 28px; font-weight: 800; color: #077bad; letter-spacing: -0.02em;">{{amount}} FCFA</p></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">Your repayment schedule and amortization details are accessible directly from your personal dashboard.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/loans" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">View loan details</a></div>',
   '["amount"]'),

  -- 9. Garantie de Prêt Requise
  ('loan_guarantee_required', 'fr', 'Action requise : Constitution de votre garantie de prêt',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #eff6ff; color: #1d4ed8; border: 1px solid #bfdbfe;">Garantie obligatoire</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Constitution de votre dépôt de garantie</h1><p style="margin: 0 0 16px; font-size: 15px; line-height: 1.6; color: #334155;">Bonjour <strong>{{client_firstname}}</strong>,</p><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Votre prêt de <strong>{{amount}} FCFA</strong> a bien été accordé et versé sur votre compte.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 4px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b;">Montant de la garantie à constituer</p><p style="margin: 0; font-size: 28px; font-weight: 800; color: #0f172a; letter-spacing: -0.02em;">{{guarantee_amount}} FCFA</p></div><p style="margin: 0 0 16px; font-size: 14px; line-height: 1.6; color: #475569;">Conformément à la réglementation microfinancière, la constitution de cette garantie obligatoire est requise pour débloquer le retrait de vos fonds. Ce montant reste votre entière propriété et vous sera intégralement restitué au terme normal de votre prêt.</p><div style="text-align: center; margin: 28px 0 12px;"><a href="https://azari-microfinance.site/client/wallet" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Constituer ma garantie</a></div>',
   '["client_firstname", "amount", "guarantee_amount"]'),

  ('loan_guarantee_required', 'en', 'Action required: Loan guarantee deposit',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #eff6ff; color: #1d4ed8; border: 1px solid #bfdbfe;">Mandatory Guarantee</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Loan guarantee requirement</h1><p style="margin: 0 0 16px; font-size: 15px; line-height: 1.6; color: #334155;">Hello <strong>{{client_firstname}}</strong>,</p><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Your loan of <strong>{{amount}} FCFA</strong> has been approved and credited to your account.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 4px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b;">Required guarantee deposit</p><p style="margin: 0; font-size: 28px; font-weight: 800; color: #0f172a; letter-spacing: -0.02em;">{{guarantee_amount}} FCFA</p></div><p style="margin: 0 0 16px; font-size: 14px; line-height: 1.6; color: #475569;">In accordance with microfinance regulations, this security deposit is necessary to activate fund withdrawals. These funds remain your full property and are returned upon successful completion of your loan.</p><div style="text-align: center; margin: 28px 0 12px;"><a href="https://azari-microfinance.site/client/wallet" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Complete guarantee deposit</a></div>',
   '["client_firstname", "amount", "guarantee_amount"]'),

  -- 10. Remboursement Confirmé
  ('repayment_confirmed', 'fr', 'Confirmation de votre remboursement',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Paiement enregistré</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Votre versement a été validé</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Nous vous confirmons la bonne réception et l''imputation comptable de votre mensualité de prêt.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 4px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b;">Montant remboursé</p><p style="margin: 0; font-size: 28px; font-weight: 800; color: #077bad; letter-spacing: -0.02em;">{{amount}} FCFA</p></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">Votre solde restant dû et le calendrier de vos prochaines échéances ont été actualisés dans votre espace client.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/loans" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Consulter mon échéancier</a></div>',
   '["amount"]'),

  ('repayment_confirmed', 'en', 'Repayment confirmed',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Repayment Confirmed</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Your repayment has been recorded</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">We confirm receipt and processing of your loan installment payment.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 4px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b;">Repaid amount</p><p style="margin: 0; font-size: 28px; font-weight: 800; color: #077bad; letter-spacing: -0.02em;">{{amount}} FCFA</p></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">Your outstanding balance and payment history have been updated in your account.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/loans" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">View schedule</a></div>',
   '["amount"]'),

  -- 11. Prêt Soldé / Clôturé
  ('loans_closed', 'fr', 'Félicitations : votre prêt est clôturé',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Prêt soldé</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Toutes vos échéances sont honorées</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Nous vous adressons toutes nos félicitations pour la clôture avec succès de votre contrat de prêt. Nous vous remercions pour la ponctualité de vos règlements.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 18px 20px; margin-bottom: 24px;"><p style="margin: 0 0 8px; font-size: 13px; font-weight: 600; color: #0f172a;">Avantages acquis :</p><ul style="margin: 0; padding-left: 18px; font-size: 14px; line-height: 1.6; color: #475569;"><li>Vos fonds de garantie bloqués ont été intégralement libérés sur votre solde</li><li>Votre historique d''emprunt exemplaire améliore votre profil de crédit</li><li>Vous êtes éligible à un montant supérieur pour votre prochain financement</li></ul></div><div style="text-align: center; margin: 28px 0 12px;"><a href="https://azari-microfinance.site/client/dashboard" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Accéder à mon espace</a></div>',
   '[]'),

  ('loans_closed', 'en', 'Your loan is complete',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;">Loan Completed</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">All installments have been paid in full</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Congratulations on the successful completion of your loan contract. We sincerely appreciate your reliability and partnership.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 18px 20px; margin-bottom: 24px;"><p style="margin: 0 0 8px; font-size: 13px; font-weight: 600; color: #0f172a;">Account updates:</p><ul style="margin: 0; padding-left: 18px; font-size: 14px; line-height: 1.6; color: #475569;"><li>Your blocked guarantee funds have been fully released to your wallet</li><li>Your positive repayment history strengthens your borrowing profile</li><li>You are eligible for higher limits on future projects</li></ul></div><div style="text-align: center; margin: 28px 0 12px;"><a href="https://azari-microfinance.site/client/dashboard" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Access my dashboard</a></div>',
   '[]'),

  -- 12. Échéance Proche (3 jours)
  ('installment_due_soon', 'fr', 'Rappel : échéance de prêt dans 3 jours',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #fffbeb; color: #b45309; border: 1px solid #fde68a;">Rappel d''échéance</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Votre prochaine mensualité arrive à échéance</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Ceci est un rappel automatique concernant le règlement de votre prochaine échéance de microcrédit.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 24px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="font-size: 14px;"><tr><td style="color: #64748b; padding-bottom: 8px;">Date limite :</td><td style="font-weight: 700; color: #0f172a; text-align: right; padding-bottom: 8px;">{{due_date}}</td></tr><tr><td style="color: #64748b;">Montant attendu :</td><td style="font-size: 20px; font-weight: 800; color: #077bad; text-align: right;">{{amount}} FCFA</td></tr></table></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">Veuillez vous assurer que votre solde de portefeuille est approvisionné afin de permettre le prélèvement sans frais additionnels.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/loans" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Régler mon échéance</a></div>',
   '["amount", "due_date"]'),

  ('installment_due_soon', 'en', 'Loan installment due in 3 days',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #fffbeb; color: #b45309; border: 1px solid #fde68a;">Payment Reminder</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Upcoming loan installment</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">This is an automated reminder regarding your upcoming microcredit installment.</p><div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 24px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="font-size: 14px;"><tr><td style="color: #64748b; padding-bottom: 8px;">Due date:</td><td style="font-weight: 700; color: #0f172a; text-align: right; padding-bottom: 8px;">{{due_date}}</td></tr><tr><td style="color: #64748b;">Amount due:</td><td style="font-size: 20px; font-weight: 800; color: #077bad; text-align: right;">{{amount}} FCFA</td></tr></table></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">Please verify that your wallet balance is topped up to allow debiting without delay.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/loans" style="display: inline-block; padding: 12px 28px; background-color: #077bad; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Pay installment</a></div>',
   '["amount", "due_date"]'),

  -- 13. Échéance en Retard
  ('installment_late', 'fr', 'Important : échéance de prêt en retard',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #fef2f2; color: #b91c1c; border: 1px solid #fecaca;">Retard constaté</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Échéance de prêt en retard de paiement</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Une mensualité de votre contrat de prêt est arrivée à échéance et n''a pas encore été régularisée.</p><div style="background-color: #fef2f2; border: 1px solid #fecaca; border-radius: 10px; padding: 20px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 4px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #991b1b;">Montant exigible</p><p style="margin: 0; font-size: 28px; font-weight: 800; color: #b91c1c; letter-spacing: -0.02em;">{{amount}} FCFA</p></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">Afin d''éviter l''application de pénalités de retard et de préserver la qualité de votre historique financier, nous vous invitons à régulariser votre solde dès aujourd''hui.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/loans" style="display: inline-block; padding: 12px 28px; background-color: #b91c1c; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Régulariser mon échéance</a></div>',
   '["amount"]'),

  ('installment_late', 'en', 'Important: loan installment overdue',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #fef2f2; color: #b91c1c; border: 1px solid #fecaca;">Overdue</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Loan installment past due</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">An installment on your loan contract is past its payment due date and remains unsettled.</p><div style="background-color: #fef2f2; border: 1px solid #fecaca; border-radius: 10px; padding: 20px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 4px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #991b1b;">Overdue amount</p><p style="margin: 0; font-size: 28px; font-weight: 800; color: #b91c1c; letter-spacing: -0.02em;">{{amount}} FCFA</p></div><p style="margin: 0 0 24px; font-size: 14px; line-height: 1.6; color: #475569;">To prevent additional late charges and maintain your good standing, please settle this installment promptly.</p><div style="text-align: center; margin: 24px 0 12px;"><a href="https://azari-microfinance.site/client/loans" style="display: inline-block; padding: 12px 28px; background-color: #b91c1c; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 8px;">Settle installment</a></div>',
   '["amount"]'),

  -- 14. Code PIN Reset OTP
  ('pin_reset_otp', 'fr', 'Votre code de réinitialisation de PIN',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #eff6ff; color: #1d4ed8; border: 1px solid #bfdbfe;">Sécurité du compte</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">Réinitialisation de votre code PIN</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">Vous avez initié une demande de réinitialisation de votre code secret PIN. Utilisez le code temporaire ci-dessous pour confirmer l''opération :</p><div style="background-color: #f8fafc; border: 2px dashed #077bad; border-radius: 12px; padding: 24px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 6px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.1em; color: #64748b;">Code de confirmation (OTP)</p><div style="font-family: ''Courier New'', Courier, monospace; font-size: 34px; font-weight: 800; letter-spacing: 8px; color: #077bad; margin: 8px 0;">{{otp}}</div><p style="margin: 6px 0 0; font-size: 13px; color: #64748b;">Ce code expire dans <strong>10 minutes</strong>.</p></div><div style="background-color: #f8fafc; border-left: 3px solid #077bad; padding: 12px 16px; margin-bottom: 20px;"><p style="margin: 0; font-size: 13px; line-height: 1.5; color: #475569;"><strong>Avis de sécurité :</strong> Ne transférez jamais ce code. Aucun conseiller ou agent Azari Microfinance ne vous demandera votre code de sécurité.</p></div>',
   '["otp"]'),

  ('pin_reset_otp', 'en', 'Your PIN reset code',
   '<div style="margin-bottom: 24px;"><span style="display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 9999px; background-color: #eff6ff; color: #1d4ed8; border: 1px solid #bfdbfe;">Account Security</span></div><h1 style="margin: 0 0 16px; font-size: 22px; font-weight: 700; color: #0f172a; line-height: 1.3;">PIN reset verification</h1><p style="margin: 0 0 20px; font-size: 15px; line-height: 1.6; color: #334155;">You requested to reset your confidential PIN. Use the one-time verification code below to authorize the update:</p><div style="background-color: #f8fafc; border: 2px dashed #077bad; border-radius: 12px; padding: 24px; margin-bottom: 24px; text-align: center;"><p style="margin: 0 0 6px; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.1em; color: #64748b;">Verification code (OTP)</p><div style="font-family: ''Courier New'', Courier, monospace; font-size: 34px; font-weight: 800; letter-spacing: 8px; color: #077bad; margin: 8px 0;">{{otp}}</div><p style="margin: 6px 0 0; font-size: 13px; color: #64748b;">Valid for <strong>10 minutes</strong> only.</p></div><div style="background-color: #f8fafc; border-left: 3px solid #077bad; padding: 12px 16px; margin-bottom: 20px;"><p style="margin: 0; font-size: 13px; line-height: 1.5; color: #475569;"><strong>Security notice:</strong> Never disclose this code. No Azari Microfinance representative will ever ask you for your code.</p></div>',
   '["otp"]')

